graphql-resolver-001.example:
```js
const resolvers = {
  Query: {
    // parent is the root value; args has { id }
    user: (parent, args, context, info) => context.db.user.findById(args.id),
  },
  User: {
    // parent is the User returned above
    posts: (user, args, context) => context.db.post.byAuthor(user.id),
  },
};
```

