graphql-sub-003.example:
```js
const resolvers = {
  Mutation: {
    addComment: async (_p, { postId, text }, { pubsub, db }) => {
      const comment = await db.comment.create({ postId, text });
      pubsub.publish(`COMMENT_ADDED_${postId}`, { commentAdded: comment });
      return comment;
    },
  },
  Subscription: {
    commentAdded: {
      subscribe: (_p, { postId }, { pubsub }) =>
        pubsub.asyncIterator(`COMMENT_ADDED_${postId}`),
    },
  },
};
```

graphql-perf-001.example:
```js
// Naïve: one DB hit per post -> N+1.
const resolvers = {
  Query: { posts: (_p, _a, { db }) => db.post.all() },
  Post: {
    // runs once PER post; 100 posts => 100 separate queries
    author: (post, _a, { db }) => db.user.findById(post.authorId),
  },
};
```

graphql-perf-002.example:
```js
import DataLoader from 'dataloader';

const userLoader = new DataLoader(async (ids) => {
  const users = await db.user.findByIds(ids);            // ONE query
  const byId = new Map(users.map((u) => [u.id, u]));
  return ids.map((id) => byId.get(id) ?? null);          // same order as ids
});

// In the Post.author resolver:
// author: (post) => userLoader.load(post.authorId)
```

